text:
:root {
  --bg: #0d1117;
  --fg: #c9d1d9;
  --accent: #22d3ee;
  --radius: 0.5rem;
  --space: 0.75rem;
}

body {
  background: var(--bg);
  color: var(--fg);
  font-family: ui-monospace, SFMono-Regular, monospace;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space);
  padding-inline: 1rem;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));
  gap: 1rem;
  align-items: start;
}

.btn {
  border: 1px solid transparent;
  border-radius: var(--radius);
  padding: 0.5rem 0.9rem;
}

.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.card {
  display: flex;
  gap: 0.75rem;
  padding: 1rem 1.25rem;
}

.card:hover > .title::after {
  content: " →";
}

@media (max-width: 40rem) {
  .card {
    flex-direction: column;
  }
}

.layout {
  display: grid;
  grid-template-areas:
    "head head"
    "side main"
    "foot foot";
  grid-template-columns: minmax(12rem, 20rem) 1fr;
  grid-template-rows: auto 1fr auto;
  min-block-size: 100dvh;
}

.layout > header {
  grid-area: head;
}

.layout > aside {
  grid-area: side;
}

:root {
  --bg: #ffffff;
  --fg: #1f2328;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0d1117;
    --fg: #c9d1d9;
  }
}

.pane {
  background: var(--bg);
  color: var(--fg);
  transition: background 150ms ease-in-out;
}

.key {
  fill: #21262d;
  stroke: #30363d;
}

.key[data-layer="lower"]:not([data-role="modifier"]) {
  fill: color-mix(in srgb, var(--accent) 25%, #21262d);
}

.key[data-next="true"]::after {
  content: "";
  animation: pulse 900ms ease-in-out infinite alternate;
}

@keyframes pulse {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0.35;
    transform: scale(1.04);
  }
}

.hint {
  animation: pulse 800ms cubic-bezier(0.4, 0, 0.2, 1) infinite alternate;
}

.pane {
  container: pane / inline-size;
}

.drill {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space);
}

@container pane (min-width: 48rem) {
  .drill {
    grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  }

  .drill > .meta {
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
  }
}

.char {
  --state: var(--fg);
  color: var(--state);
}

.char[data-state="correct"] {
  --state: #3fb950;
}

.char[data-state="wrong"] {
  --state: #f85149;
  text-decoration: underline wavy currentColor;
}

.char:nth-child(2n + 1):hover::before {
  content: attr(data-key);
  position: absolute;
  translate: 0 -1.4em;
}

.sheet {
  --gutter: clamp(1rem, 4vw, 3rem);
  display: grid;
  grid-template-columns:
    [full-start] var(--gutter)
    [content-start] minmax(0, 64rem)
    [content-end] var(--gutter)
    [full-end];
}

.sheet > * {
  grid-column: content;
}

@media print {
  .sheet {
    --gutter: 0;
    color: #000;
  }
}

.tabs {
  display: flex;
  gap: 0.25rem;
  border-block-end: 1px solid #30363d;
}

.tabs > button {
  position: relative;
  padding: 0.5rem 1rem;
  transition: color 150ms ease;
}

.tabs > button[aria-selected="true"]::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  inset-block-end: -1px;
  block-size: 2px;
  background: var(--accent);
}

@supports (position: sticky) {
  .minimap {
    position: sticky;
    inset-block-start: var(--space);
    max-block-size: calc(100dvh - var(--space) * 2);
    overflow: auto;
    scrollbar-width: thin;
  }
}

@media (max-width: 60rem) {
  .minimap {
    position: static;
    max-block-size: none;
  }
}
